import api from './api';

export const shareLinkService = {
  /**
   * Create a new share link with chosen expiry
   */
  createShareLink: async ({ expiryHours, customExpiresAt, label }) => {
    const response = await api.post('/share-links', {
      expiryHours,
      customExpiresAt,
      label,
    });
    return response.data;
  },

  /**
   * Get all share links generated by current user
   */
  getMyShareLinks: async () => {
    const response = await api.get('/share-links');
    return response.data;
  },

  /**
   * Revoke an active share link immediately
   */
  revokeShareLink: async (id) => {
    const response = await api.post(`/share-links/${id}/revoke`);
    return response.data;
  },

  /**
   * Get all remarks left on current user's records
   */
  getMyRemarks: async (params = {}) => {
    const response = await api.get('/share-links/remarks', { params });
    return response.data;
  },

  /**
   * Mark a single remark as read
   */
  markRemarkAsRead: async (id) => {
    const response = await api.patch(`/share-links/remarks/${id}/read`);
    return response.data;
  },

  /**
   * Mark all remarks as read for current user
   */
  markAllRemarksAsRead: async () => {
    const response = await api.patch('/share-links/remarks/read-all');
    return response.data;
  },

  /**
   * Get unread remarks count for current user
   */
  getUnreadRemarksCount: async () => {
    const response = await api.get('/share-links/remarks/unread-count');
    return response.data;
  },
};

export default shareLinkService;
